"""Product analytics dashboard: conversion statistics over customer sessions."""


def conversion_rate(events):
    """Return the share of sessions whose ``converted`` value is True."""
    if not events:
        return 0.0
    hits = sum(1 for event in events if event["converted"] is True)
    return hits / len(events)


def pooled_conversion_rate(groups):
    """Return the conversion rate across all sessions in all groups."""
    total_sessions = 0
    converted_sessions = 0
    for events in groups.values():
        total_sessions += len(events)
        converted_sessions += sum(1 for event in events if event["converted"] is True)
    if total_sessions == 0:
        return 0.0
    return converted_sessions / total_sessions


def conversions_in_window(daily_counts, days):
    """Sum the last ``days`` entries of daily counts (oldest first)."""
    if days <= 0:
        return 0
    return sum(daily_counts[-days:])


def conversion_rate_by_group(groups):
    """Return conversion rates by group, with group names in ascending order."""
    return {
        name: conversion_rate(events) if events else None
        for name, events in sorted(groups.items())
    }


def longest_conversion_streak(daily_counts):
    """Return the longest run of consecutive positive daily counts."""
    best = current = 0
    for count in daily_counts:
        if count > 0:
            current += 1
            best = max(best, current)
        else:
            current = 0
    return best

"""Product analytics dashboard: parsing and aggregating customer sessions."""


def parse_session_log(lines):
    """Parse session log lines into session dictionaries."""
    out = []
    for line_number, line in enumerate(lines, start=1):
        stripped = line.strip()
        if not stripped or stripped.startswith("#"):
            continue

        fields = [field.strip() for field in line.split(",")]
        if len(fields) != 3:
            raise ValueError(f"line {line_number}: expected exactly three fields")

        session_id, day_text, converted_text = fields
        try:
            day = int(day_text)
        except ValueError as error:
            raise ValueError(f"line {line_number}: day must be an integer") from error

        if converted_text == "1":
            converted = True
        elif converted_text == "0":
            converted = False
        elif converted_text == "":
            converted = None
        else:
            raise ValueError(f"line {line_number}: converted must be 1, 0, or empty")

        out.append({"id": session_id, "day": day, "converted": converted})
    return out


def dedupe_sessions(events):
    """Keep the last record for each id, sorted by day and then id."""
    latest_by_id = {}
    for event in events:
        latest_by_id[event["id"]] = event
    return sorted(latest_by_id.values(), key=lambda event: (event["day"], event["id"]))


def daily_conversion_counts(events, start_day, end_day):
    """Count converted sessions on each day in the inclusive day range."""
    if end_day < start_day:
        return []

    counts = {day: 0 for day in range(start_day, end_day + 1)}
    for event in events:
        day = event["day"]
        if start_day <= day <= end_day and event["converted"] is True:
            counts[day] += 1
    return [counts[day] for day in range(start_day, end_day + 1)]

"""Product analytics dashboard: campaign reports."""
from sales_dashboard.loader import daily_conversion_counts
from sales_dashboard.metrics import (
    conversions_in_window,
    conversion_rate,
    pooled_conversion_rate,
)


def campaign_summary(groups, days):
    """Summarize pooled conversion, recent conversions, and nonempty groups."""
    all_events = [event for events in groups.values() for event in events]
    if all_events:
        first_day = min(event["day"] for event in all_events)
        last_day = max(event["day"] for event in all_events)
        daily_counts = daily_conversion_counts(all_events, first_day, last_day)
        recent = conversions_in_window(daily_counts, days)
    else:
        recent = 0

    return {
        "rate": round(pooled_conversion_rate(groups), 3),
        "recent": recent,
        "groups": sum(1 for events in groups.values() if events),
    }


def top_converting_groups(groups, n):
    """Return up to ``n`` nonempty groups by rate, then group name."""
    ranked = [
        (name, conversion_rate(events))
        for name, events in groups.items()
        if events
    ]
    ranked.sort(key=lambda item: (-item[1], item[0]))
    return [name for name, _rate in ranked[:n]]

